import { spawn, type ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'

import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { expectedTestLinkMcp } from '../src/mcp-testlink-client.js'

/**
 * What this proves: a Test Case submitted through the running server lands in a
 * real TestLink, and the id the write answers with is the id a read of that
 * TestLink answers to.
 *
 * And the same write refused: a clean Test Case addressed to a Test Suite
 * TestLink does not hold is answered as the caller's own mistake — a 404 naming
 * what is missing, carrying no violations — and TestLink holds no new Test Case
 * anywhere afterwards. That claim is about wording rather than about a status
 * code: `McpTestLinkClient` decides between absence and an outage by matching
 * the words TestLink failed in, and every other file here matches that reading
 * against strings the suite itself wrote. Only a real TestLink can say whether
 * the words it actually fails in are the words being matched.
 *
 * It is the one thing the rest of the suite cannot say. Every other file here
 * substitutes TestLink — `stub-testlink-client.ts` — or Postgres — `pg-mem` —
 * and none of them imports `src/server.ts` at all, so an id invented in the
 * answer and never stored would pass all of them. This file starts the real
 * entry point the way `npm run dev` does, and every hop below it is the real
 * one: the real testlink-mcp container, the real TestLink, the real database.
 *
 * Nothing is substituted. One thing is configured rather than defaulted, and it
 * is named here because it is the seam that would otherwise be silent:
 * `src/server.ts` launches testlink-mcp in a container with no `--network`
 * flag, which cannot reach a TestLink published on the host's own localhost —
 * the address `.env.example` documents and `.mcp.json` uses. So the launch is
 * overridden with the host-network form `.mcp.json` already carries, through
 * the two settings the server reads for exactly this purpose. The version is
 * imported from the client rather than restated, so it cannot drift from the
 * testlink-mcp the client is written against. Set TESTLINK_MCP_COMMAND and
 * TESTLINK_MCP_ARGS in the environment to launch it some other way.
 *
 * What it needs, none of which it creates for itself:
 *
 *   docker compose up -d
 *   psql "$DATABASE_URL" -f schema.sql
 *   psql "$DATABASE_URL" -f default-rules.sql
 *
 * and a `.env` naming that database, that TestLink and an API key for it. With
 * any of them absent this file fails rather than skips: it exists to be the
 * check that cannot pass while the real path is broken.
 */

/** Where this run's server listens. Not 3000 or the .env PORT: a server already up is not this one. */
const port = Number(process.env.SYSTEM_TEST_PORT ?? 8131)
const server = `http://127.0.0.1:${port}`

const repository = fileURLToPath(new URL('..', import.meta.url))

/**
 * The fixture Project and Test Suite this write is placed in, and the Test Case
 * it writes. Stable names, never suffixed: a run that dies before its teardown
 * leaves them findable, so the next run reuses what it finds instead of filling
 * TestLink with near-duplicates. The prefix is stamped into the Project forever
 * and TestLink will not have two, which is another reason not to generate one.
 */
const fixture = {
  project: { name: 'Validator System Test', prefix: 'VSTX' },
  suite: { name: 'Write and read back' },
  /**
   * Wording chosen to violate none of the shipped Rules — no colon, no hyphen,
   * none of the terms in `default-rules.sql` — because a Rejection is a 422 and
   * this file is not about what the Rules do. If the Rules grow to catch this,
   * the failure says so: the body of a 422 names the Rule that fired.
   */
  testCase: {
    name: 'Guest device joins the open SSID',
    summary: 'A guest device associates with the open SSID and loads the portal page.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /**
   * The Test Suite that supplies an id TestLink does not hold. It is placed and
   * then removed, so the id handed on is one TestLink issued and has given up,
   * rather than a number picked for being free — a number free today is a
   * number some later run finds taken, and a check against one is a check
   * against arithmetic instead of against absence.
   */
  removedSuite: { name: 'Removed so its id is held by nothing' },
  /**
   * The Test Case addressed to that id. A name of its own rather than the one
   * above, because the claim is that TestLink holds no Test Case under it and
   * the write above puts that one in the fixture Suite on purpose. Worded to
   * violate no shipped Rule for the same reason as the write: a Rejection is a
   * 422 and would never reach TestLink at all.
   */
  refusedCase: {
    name: 'Guest device roams between access points',
    summary: 'A guest device moves between two access points and keeps the portal session.',
    preconditions: 'Both access points broadcast the open SSID.',
  },
}

/** What the server answered, kept whole so a failure can quote it. */
interface Answer {
  status: number
  text: string
  body: any
}

async function call(method: string, path: string, payload?: unknown): Promise<Answer> {
  const response = await fetch(`${server}${path}`, {
    method,
    ...(payload === undefined
      ? {}
      : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }),
  })
  const text = await response.text()

  return { status: response.status, text, body: text === '' ? undefined : JSON.parse(text) }
}

/**
 * The answer, or a failure naming what was asked and what came back. Written as
 * a throw rather than an expectation so the same reading works in a hook: a
 * TestLink that is not answering has to say so where it happened, not as an
 * undefined further down.
 */
function answered(what: string, answer: Answer, status: number): Answer {
  if (answer.status !== status) {
    throw new Error(`${what} answered ${answer.status} rather than ${status}: ${answer.text}`)
  }

  return answer
}

/**
 * A listing, reading a Project or a Test Suite that holds nothing yet as the
 * empty listing it is.
 *
 * TestLink reports "is empty" as an API failure rather than as an empty result,
 * and `McpTestLinkClient` matches only "does not exist" and "not found", so that
 * wording escalates as an outage and the server answers 500. That is worth an
 * issue of its own and it is not what this file is about: it shows up only on
 * the way to placing the fixture, on the first run against a TestLink that has
 * never held it. Read here, in the fixture path alone — every answer the claim
 * itself reads is demanded outright.
 */
function listed(what: string, answer: Answer): { id: string; name: string }[] {
  if (answer.status === 500 && /is empty/i.test(answer.text)) {
    return []
  }

  return answered(what, answer, 200).body as { id: string; name: string }[]
}

let serverProcess: ChildProcess
/** Everything the server said, so a start that never completes reports its own reason. */
let said = ''
let projectId: string
let suiteId: string
let absentSuiteId: string
let writtenId: string | undefined

/** The real entry point, launched the way `npm run dev` launches it. */
async function startServer(): Promise<void> {
  serverProcess = spawn('npx', ['tsx', '--env-file-if-exists=.env', 'src/server.ts'], {
    cwd: repository,
    // Set here rather than in .env: what is set in the environment wins over the
    // file, so this names the port and the launch without editing anything.
    env: {
      ...process.env,
      PORT: String(port),
      TESTLINK_MCP_COMMAND: process.env.TESTLINK_MCP_COMMAND ?? 'docker',
      TESTLINK_MCP_ARGS:
        process.env.TESTLINK_MCP_ARGS ??
        JSON.stringify([
          'run',
          '--rm',
          '-i',
          '--network',
          'host',
          '-e',
          'TESTLINK_URL',
          '-e',
          'TESTLINK_API_KEY',
          `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
        ]),
    },
    // Its own group, so stopping it stops the testlink-mcp it spawned as well.
    detached: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })

  serverProcess.stdout?.on('data', (chunk) => (said += chunk))
  serverProcess.stderr?.on('data', (chunk) => (said += chunk))

  // Readiness is asked of the route that reads only the database, so a TestLink
  // that is down is reported by the step that needed it rather than as a server
  // that never started.
  for (let attempt = 0; attempt < 120; attempt++) {
    if (serverProcess.exitCode !== null) {
      throw new Error(`The server exited with ${serverProcess.exitCode} before it listened: ${said}`)
    }

    try {
      await call('GET', '/reference-documents')
      return
    } catch {
      await new Promise((wait) => setTimeout(wait, 500))
    }
  }

  throw new Error(`The server did not listen on ${port}: ${said}`)
}

function stopServer(): void {
  if (serverProcess?.pid !== undefined && serverProcess.exitCode === null) {
    try {
      process.kill(-serverProcess.pid, 'SIGTERM')
    } catch {
      serverProcess.kill('SIGTERM')
    }
  }
}

/** The fixture Project, reused where TestLink already holds one under this name. */
async function placeProject(): Promise<string> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)
  const held = (projects.body as { id: string; name: string }[]).find(
    (project) => project.name === fixture.project.name,
  )

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Project ${fixture.project.name}`,
    await call('POST', '/projects', {
      ...fixture.project,
      notes: 'Fixture Project for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/** The fixture Test Suite under it, reused the same way and for the same reason. */
async function placeSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.suite.name)

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Test Suite ${fixture.suite.name}`,
    await call('POST', `/projects/${projectId}/suites`, {
      ...fixture.suite,
      details: 'Fixture Test Suite for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/**
 * A Test Suite id TestLink no longer holds. Placed under the fixture Project and
 * removed again, because absence has to be something TestLink demonstrated
 * rather than something this file assumed: TestLink issues node ids from a
 * sequence and does not issue one twice, so an id it has given up is an id it
 * will never hold again.
 *
 * The name is stable and never suffixed, so a run that died between the place
 * and the remove leaves a Test Suite the next run finds and removes rather than
 * a second one beside it. The removal is verified before the id is handed on,
 * because an id whose Test Suite is still there would prove the opposite of what
 * the claim needs and would do it silently.
 */
async function placeAndRemoveSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.removedSuite.name)

  const id =
    held !== undefined
      ? String(held.id)
      : String(
          answered(
            `Creating Test Suite ${fixture.removedSuite.name}`,
            await call('POST', `/projects/${projectId}/suites`, {
              ...fixture.removedSuite,
              details:
                'Placed and removed by the system test, so that its id is one TestLink holds nothing under.',
            }),
            201,
          ).body.id,
        )

  answered(
    `Removing Test Suite ${id}`,
    await call('DELETE', `/projects/${projectId}/suites/${id}`),
    204,
  )

  const remaining = listed(
    `Listing the Test Suites of Project ${projectId} after removing ${id}`,
    await call('GET', `/projects/${projectId}/suites`),
  )

  if (remaining.some((suite) => String(suite.id) === id)) {
    throw new Error(`Test Suite ${id} is still in Project ${projectId}, so its id is not free.`)
  }

  return id
}

/**
 * How many Test Cases TestLink has issued an id for, per Project — its own
 * count, served with every Project it lists. A count that has not moved in any
 * Project is TestLink having created no Test Case anywhere, which is what the
 * refusal below has to be true of and what listing one Test Suite cannot say.
 */
async function testCaseCounts(): Promise<Record<string, string>> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)

  return Object.fromEntries(
    (projects.body as { id: string; tc_counter: string }[]).map((project) => [
      String(project.id),
      String(project.tc_counter),
    ]),
  )
}

/**
 * A Test Case this fixture name is already on, from a run that failed before its
 * teardown. Removed rather than written beside, so the write below is the only
 * one under that name and a leak cannot accumulate.
 */
async function removeLeftovers(): Promise<void> {
  const cases = listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  )

  for (const held of cases) {
    if (held.name === fixture.testCase.name) {
      answered(
        `Removing the leftover Test Case ${held.id}`,
        await call('DELETE', `/test-cases/${held.id}`),
        204,
      )
    }
  }
}

describe('a Test Case written through the running server', () => {
  beforeAll(async () => {
    await startServer()
    projectId = await placeProject()
    suiteId = await placeSuite()
    absentSuiteId = await placeAndRemoveSuite()
    await removeLeftovers()
  }, 120_000)

  afterAll(async () => {
    try {
      if (writtenId !== undefined) {
        answered(
          `Removing the Test Case ${writtenId} this run created`,
          await call('DELETE', `/test-cases/${writtenId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${writtenId}`,
          await call('GET', `/test-cases/${writtenId}`),
          404,
        )
      }
    } finally {
      stopServer()
    }
  }, 60_000)

  it('lands in TestLink under the id the write answered with', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.testCase),
      201,
    )

    writtenId = String(written.body.id)
    expect(writtenId).not.toBe('')

    // The id is TestLink's own, not one this answer minted: TestLink's tree
    // reports the Test Case under it, with the Fields that were sent.
    const inSuite = answered(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
      200,
    )
    expect((inSuite.body as { id: string }[]).map((held) => String(held.id))).toContain(writtenId)

    // And the read the API serves answers to that same id, with what was
    // written rather than with what the write was told.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.testCase)
  }, 60_000)

  it('is refused as absence when TestLink holds no such Test Suite, and writes nothing', async () => {
    const before = await testCaseCounts()

    // Demanded as a 404 rather than read for one: how the failure is worded is
    // the claim, so a run that gets some other answer has to quote what TestLink
    // actually said. A 500 here is `McpTestLinkClient` failing to recognise
    // TestLink's own wording for a Test Suite that is not there, and a 422 is a
    // Rule having fired on the Test Case before TestLink was ever reached.
    const refused = answered(
      `Submitting to Test Suite ${absentSuiteId}, which TestLink does not hold`,
      await call('POST', `/projects/${projectId}/suites/${absentSuiteId}/test-cases`, fixture.refusedCase),
      404,
    )

    // Nothing was refused, so nothing is reported as refused: an answer carrying
    // violations would be a Rejection, and this caller has an id to correct
    // rather than wording to fix.
    expect(refused.body).not.toHaveProperty('violations')
    expect(refused.body.message).toContain(absentSuiteId)

    // The infrastructure, which is what separates this from a status code any
    // substitute could produce: TestLink issued no Test Case id in any Project,
    // and the Test Suite the write would have landed in holds nothing under the
    // name that was sent.
    expect(await testCaseCounts()).toEqual(before)

    const inSuite = listed(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
    )
    expect(inSuite.map((held) => held.name)).not.toContain(fixture.refusedCase.name)
  }, 60_000)
})

import Fastify, {
  type FastifyError,
  type FastifyInstance,
  type FastifyReply,
  type FastifyRequest,
  type FastifyServerOptions,
} from 'fastify'

import type { DocumentStore } from './reference-document.js'
import { bindRules, ruleSetVersionOf, type StoredRule } from './rule-set.js'
import type {
  NewProject,
  NewTestSuite,
  ProjectChanges,
  TestCase,
  TestLinkClient,
  TestSuiteChanges,
} from './testlink-client.js'
import { findViolations, type Violation } from './violation.js'

/**
 * The Field structure of a Test Case. A submission that does not match it is
 * refused before any Rule evaluation runs. `satisfies` keeps the schema and the
 * TestCase type from drifting apart: a Field added to one must appear in both.
 */
const testCaseSchema = {
  type: 'object',
  required: ['name', 'summary'],
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    summary: { type: 'string' },
    preconditions: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  required: readonly (keyof TestCase)[]
  additionalProperties: false
  properties: Record<keyof Required<TestCase>, { type: string }>
}

/** The settings a Project carries, shared by the shapes that create and change one. */
const projectSettings = {
  notes: { type: 'string' },
  active: { type: 'boolean' },
  isPublic: { type: 'boolean' },
  requirementsEnabled: { type: 'boolean' },
  testPriorityEnabled: { type: 'boolean' },
  automationEnabled: { type: 'boolean' },
  inventoryEnabled: { type: 'boolean' },
} as const

/** What a caller says about a Project it is creating. */
const newProjectSchema = {
  type: 'object',
  required: ['name', 'prefix'],
  additionalProperties: false,
  properties: { name: { type: 'string' }, prefix: { type: 'string' }, ...projectSettings },
} as const satisfies {
  type: 'object'
  required: readonly (keyof NewProject)[]
  additionalProperties: false
  properties: Record<keyof Required<NewProject>, { type: string }>
}

/**
 * What a caller may change about a Project. At least one, because TestLink
 * refuses a change that names none and a caller reads that as its own mistake
 * sooner if it is refused here.
 */
const projectChangesSchema = {
  type: 'object',
  minProperties: 1,
  additionalProperties: false,
  properties: { name: { type: 'string' }, color: { type: 'string' }, ...projectSettings },
} as const satisfies {
  type: 'object'
  minProperties: number
  additionalProperties: false
  properties: Record<keyof Required<ProjectChanges>, { type: string }>
}

/**
 * Deleting a Project takes everything under it, so the caller restates the
 * Project's own prefix and the delete is refused without it.
 */
const deleteProjectSchema = {
  type: 'object',
  required: ['confirmPrefix'],
  additionalProperties: false,
  properties: { confirmPrefix: { type: 'string' } },
} as const

/**
 * What a caller says about a Test Suite it is creating, and where to put it.
 * Held to the same drift check as the Test Case schema above.
 */
const newTestSuiteSchema = {
  type: 'object',
  required: ['name'],
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    details: { type: 'string' },
    parentSuiteId: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  required: readonly (keyof NewTestSuite)[]
  additionalProperties: false
  properties: Record<keyof Required<NewTestSuite> | 'parentSuiteId', { type: string }>
}

/** What a caller may change about a Test Suite. Its place in the Project is not one of them. */
const testSuiteChangesSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    details: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  additionalProperties: false
  properties: Record<keyof Required<TestSuiteChanges>, { type: string }>
}

export function buildApp({
  testlink,
  documents,
  rules,
  logger = false,
}: {
  testlink: TestLinkClient
  /** Where the Reference Documents are read from. Read only — nothing here writes one. */
  documents: DocumentStore
  /** The operator's enabled Rules, as the database holds them. Bound once here and never re-read. */
  rules: StoredRule[]
  /**
   * Where the server logs, off unless the entry point turns it on. Logs are
   * observability alone: nothing written here is read back, and no logged data
   * reaches a validation outcome.
   */
  logger?: FastifyServerOptions['logger']
}): FastifyInstance {
  // Binding happens before the server exists, so an invalid Rule leaves nothing
  // to call rather than a server running without its Rules.
  const bound = bindRules(rules)

  // Fixed for the life of the process, because the Rules are read once and
  // never reloaded.
  const ruleSetVersion = ruleSetVersionOf(rules)

  // Coercion off: a Field of the wrong type is refused, not quietly converted
  // into one that passes.
  const app = Fastify({ logger, ajv: { customOptions: { coerceTypes: false } } })

  // The envelope names the Rules this server is running, on every answer without
  // exception — a delete, which has no body to carry them, included.
  app.addHook('onSend', async (_request, reply) => {
    reply.header('Rule-Set-Version', ruleSetVersion)
  })

  /**
   * The version in the answer itself, where the Rules judged what was sent.
   * Callers are agents that read the body, so an answer the Rules took part in
   * names them in it rather than only on the envelope. An answer no Rule reached
   * — a schema refusal, or content TestLink did not hold — carries no version in
   * its body, because the Rules contributed nothing to it.
   */
  const versioned = <T extends object>(body: T) => ({ ...body, ruleSetVersion })

  /**
   * A Rejection, and the log lines that make a Rule firing over and over
   * visible — the signal separating a Rule that cannot be satisfied from an
   * agent that writes badly once. Nothing is counted here and nothing is read
   * back, so the same Test Case submitted twice is answered identically.
   */
  const reject = (request: FastifyRequest, reply: FastifyReply, violations: Violation[]) => {
    for (const { field, rule } of violations) {
      request.log.warn({ ruleSetVersion, field, rule }, 'Rule violated')
    }

    return reply.code(422).send(versioned({ violations }))
  }

  // A schema refusal carries no violations, so it cannot be read as a Rejection.
  app.setErrorHandler((error: FastifyError, _request, reply) => {
    if (error.validation) {
      return reply.code(400).send({ refusal: 'schema', message: error.message })
    }
    return reply.send(error)
  })

  /**
   * What TestLink holds nothing under is the caller's to correct, so it answers
   * as a client error — where TestLink being unreachable, which is the server's
   * to recover from, answers as a server one. Nothing was refused here, so this
   * carries no `refusal` and no violations: there was simply nothing to act on.
   */
  const nothingThere = (reply: FastifyReply, what: string) =>
    reply.code(404).send({ message: `TestLink holds no ${what}.` })

  app.post<{ Params: { projectId: string; suiteId: string }; Body: TestCase }>(
    '/projects/:projectId/suites/:suiteId/test-cases',
    { schema: { body: testCaseSchema } },
    async (request, reply) => {
      const violations = findViolations(request.body, bound.testCase)

      // A Rejection is the whole outcome: nothing is written, and the caller
      // reads a client error, where TestLink being unreachable is a server one.
      if (violations.length > 0) {
        return reject(request, reply, violations)
      }

      const { projectId, suiteId } = request.params
      const written = await testlink.createTestCase({ projectId, suiteId }, request.body)

      // Which of the two TestLink is missing is not something it says, so the
      // answer names both rather than guessing at one.
      if (written === undefined) {
        return nothingThere(reply, `Test Suite ${suiteId} in Project ${projectId}`)
      }

      return reply.code(201).send(versioned(written))
    },
  )

  app.get<{ Params: { id: string } }>('/test-cases/:id', async (request, reply) => {
    const testCase = await testlink.getTestCase(request.params.id)

    if (testCase === undefined) {
      return nothingThere(reply, `Test Case ${request.params.id}`)
    }

    // A read is never refused, whatever fired on what it serves: refusing would
    // put the content out of reach, and the caller reading it is the one who
    // needs to see what is wrong with it. The Violations sit beside the content
    // rather than in it, so what is served is what is stored.
    return reply.send(versioned({ testCase, violations: findViolations(testCase, bound.testCase) }))
  })

  // An update is a write, so the Rules run on it exactly as they run on a
  // submission. It answers with a status code of its own, so a caller knows
  // whether it added a Test Case or replaced one without reading the body.
  app.put<{ Params: { id: string }; Body: TestCase }>(
    '/test-cases/:id',
    { schema: { body: testCaseSchema } },
    async (request, reply) => {
      const violations = findViolations(request.body, bound.testCase)

      if (violations.length > 0) {
        return reject(request, reply, violations)
      }

      const applied = await testlink.updateTestCase(request.params.id, request.body)

      if (!applied) {
        return nothingThere(reply, `Test Case ${request.params.id}`)
      }

      return reply.send(versioned({ id: request.params.id }))
    },
  )

  app.delete<{ Params: { id: string } }>('/test-cases/:id', async (request, reply) => {
    const deleted = await testlink.deleteTestCase(request.params.id)

    if (!deleted) {
      return nothingThere(reply, `Test Case ${request.params.id}`)
    }

    return reply.code(204).send()
  })

  // TestLink's own structure, served straight through. No Rule binds to a
  // Project or a Test Suite — Rules are bound to the Fields of a Test Case — so
  // there is nothing here to check and nothing to attach.
  app.get('/projects', async () => testlink.listProjects())

  app.post<{ Body: NewProject }>(
    '/projects',
    { schema: { body: newProjectSchema } },
    async (request, reply) => reply.code(201).send(await testlink.createProject(request.body)),
  )

  app.put<{ Params: { projectId: string }; Body: ProjectChanges }>(
    '/projects/:projectId',
    { schema: { body: projectChangesSchema } },
    async (request, reply) => {
      const { projectId } = request.params
      const applied = await testlink.updateProject(projectId, request.body)

      if (!applied) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.send({ id: projectId })
    },
  )

  app.delete<{ Params: { projectId: string }; Querystring: { confirmPrefix: string } }>(
    '/projects/:projectId',
    { schema: { querystring: deleteProjectSchema } },
    async (request, reply) => {
      const { projectId } = request.params
      const deletion = await testlink.deleteProject(projectId, request.query.confirmPrefix)

      if (deletion === 'absent') {
        return nothingThere(reply, `Project ${projectId}`)
      }

      // Nothing was deleted and nothing is wrong with TestLink: the caller
      // restated the wrong prefix, and reads that rather than an outage.
      if (deletion === 'unconfirmed') {
        return reply.code(409).send({
          message: `The prefix given does not match Project ${projectId}, so nothing was deleted.`,
        })
      }

      return reply.code(204).send()
    },
  )

  app.get<{ Params: { projectId: string }; Querystring: { parentSuiteId?: string } }>(
    '/projects/:projectId/suites',
    async (request, reply) => {
      const { projectId } = request.params
      const listed = await testlink.listTestSuites(projectId, request.query.parentSuiteId)

      if (listed === undefined) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.send(listed)
    },
  )

  app.get<{ Params: { projectId: string; suiteId: string } }>(
    '/projects/:projectId/suites/:suiteId/test-cases',
    async (request, reply) => {
      const { suiteId } = request.params
      const listed = await testlink.listTestCasesInSuite(suiteId)

      if (listed === undefined) {
        return nothingThere(reply, `Test Suite ${suiteId}`)
      }

      return reply.send(listed)
    },
  )

  app.post<{ Params: { projectId: string }; Body: NewTestSuite & { parentSuiteId?: string } }>(
    '/projects/:projectId/suites',
    { schema: { body: newTestSuiteSchema } },
    async (request, reply) => {
      const { name, details, parentSuiteId } = request.body
      const { projectId } = request.params
      const created = await testlink.createTestSuite(projectId, { name, details }, parentSuiteId)

      if (created === undefined) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.code(201).send(created)
    },
  )

  app.put<{ Params: { projectId: string; suiteId: string }; Body: TestSuiteChanges }>(
    '/projects/:projectId/suites/:suiteId',
    { schema: { body: testSuiteChangesSchema } },
    async (request, reply) => {
      const { projectId, suiteId } = request.params
      const applied = await testlink.updateTestSuite(projectId, suiteId, request.body)

      if (!applied) {
        return nothingThere(reply, `Test Suite ${suiteId}`)
      }

      return reply.send({ id: suiteId })
    },
  )

  // TestLink identifies a Test Suite on its own, so the Project the caller
  // named is where it is addressed from rather than part of what is deleted.
  app.delete<{ Params: { projectId: string; suiteId: string } }>(
    '/projects/:projectId/suites/:suiteId',
    async (request, reply) => {
      const deleted = await testlink.deleteTestSuite(request.params.suiteId)

      if (!deleted) {
        return nothingThere(reply, `Test Suite ${request.params.suiteId}`)
      }

      return reply.code(204).send()
    },
  )

  /**
   * The Reference Documents, which the generating agent reads instead of holding
   * files of its own. A caller names a document by its id and nothing else: no
   * path reaches this API, so there is no filesystem for a caller to describe or
   * to walk out of.
   *
   * Read only. A document the agent could write is a document it could author in
   * the style the Rules exist to catch and then read back as authority, which is
   * the same reason it cannot reload a Rule.
   */
  app.get('/reference-documents', async () => documents.listDocuments())

  app.get<{ Params: { id: string } }>('/reference-documents/:id', async (request, reply) => {
    const { id } = request.params
    const document = await documents.getDocument(id)

    // A client error, told apart from a Rejection by carrying no violations at
    // all, and from the database being unreachable — which throws, and answers
    // as a server error — by status code alone.
    if (document === undefined) {
      return reply.code(404).send({ message: `There is no Reference Document ${id}.` })
    }

    // Checked at read time, exactly as a Test Case is. This is the read path
    // ADR-0003 leaves as the only channel by which the agent sees existing
    // content, so a document carrying the wording the Rules catch says so rather
    // than teaching it on. Never refused, however much fired: refusing would put
    // the document out of reach of the caller who most needs to see what is
    // wrong with it.
    return reply.send(
      versioned({ document, violations: findViolations(document, bound.referenceDocument) }),
    )
  })

  return app
}

import { buildApp } from './app.js'
import { expectedTestLinkMcp, McpTestLinkClient } from './mcp-testlink-client.js'
import { connectToPostgres, PostgresStore } from './postgres-store.js'
import { required } from './setting.js'
import { connectToTestLinkMcp } from './stdio-tool-caller.js'

/**
 * The database, which holds the Rules and the Reference Documents. Read only
 * from here: what is in it was written by an operator with SQL, and this project
 * ships nothing that writes to it (ADR-0006).
 */
const store = new PostgresStore(await connectToPostgres(required('DATABASE_URL')))

/**
 * Read once, here, and never again — the property ADR-0004 keeps when it moves
 * Rules out of a file. A database with none enabled in it is missing in the same
 * way an invalid Rule is: there is no point starting a server that would accept
 * every write it is given.
 */
const rules = await store.rules()

if (rules.length === 0) {
  throw new Error(
    'No enabled Rules are in the database, so the server will not start. Apply schema.sql and insert a Rule — the README has the statements.',
  )
}

/**
 * How to launch testlink-mcp. It documents two ways of being run — the
 * published container and a checkout of its source — so both are reachable
 * here; the container is the default because it is the documented one. The
 * arguments are read as JSON so that a path with a space in it survives, which
 * is also the shape every MCP client configuration writes them in.
 *
 * The container is pinned to the version the client calls rather than tracking
 * `latest`. A tag is not a version: Docker will not re-pull one it already
 * holds, so `latest` is whatever it meant the first time a host pulled it, and
 * a host that pulled before a tool existed keeps a server without it.
 */
function testLinkMcp(): { command: string; args: string[] } {
  const command = process.env.TESTLINK_MCP_COMMAND

  if (command === undefined) {
    return {
      command: 'docker',
      args: [
        'run',
        '--rm',
        '-i',
        '-e',
        'TESTLINK_URL',
        '-e',
        'TESTLINK_API_KEY',
        `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
      ],
    }
  }

  try {
    return { command, args: JSON.parse(required('TESTLINK_MCP_ARGS')) }
  } catch (error) {
    throw new Error(
      `TESTLINK_MCP_ARGS must be a JSON list of arguments, so the server will not start: ${
        (error as Error).message
      }`,
    )
  }
}

const tools = await connectToTestLinkMcp({
  ...testLinkMcp(),
  env: {
    ...process.env,
    TESTLINK_URL: required('TESTLINK_URL'),
    TESTLINK_API_KEY: required('TESTLINK_API_KEY'),
  } as Record<string, string>,
})

const app = buildApp({
  testlink: new McpTestLinkClient(tools, { authorLogin: required('TESTLINK_AUTHOR_LOGIN') }),
  documents: store,
  rules,
  // Violations and outages, and not a line per request: what is logged is what
  // an operator is meant to read, and request logging was not asked for.
  logger: { level: 'warn' },
})

await app.listen({ port: Number(process.env.PORT ?? 3000), host: '0.0.0.0' })

import type {
  NewProject,
  NewTestSuite,
  Placement,
  ProjectChanges,
  ProjectDeletion,
  TestCase,
  TestLinkClient,
  TestLinkContent,
  TestSuiteChanges,
} from './testlink-client.js'
import type { ToolCaller } from './tool-caller.js'

/**
 * The real path to TestLink, through the testlink-mcp tools. Everything this
 * client does is one tool call and one reading of what came back, so the whole
 * of its judgement is in `answer` below: which failures are something that is
 * not there, and which are TestLink not answering at all.
 */
export class McpTestLinkClient implements TestLinkClient {
  constructor(
    private readonly tools: ToolCaller,
    /** Who the validator writes as. The one piece of TestLink identity a caller does not supply. */
    private readonly config: { authorLogin: string },
  ) {}

  async createTestCase(
    { projectId, suiteId }: Placement,
    testCase: TestCase,
  ): Promise<{ id: string } | undefined> {
    const written = await this.answer('create_test_case', {
      data: {
        testprojectid: projectId,
        testsuiteid: suiteId,
        name: testCase.name,
        authorlogin: this.config.authorLogin,
        ...fieldsOf(testCase),
      },
    })

    if (written === absent) {
      return undefined
    }

    return { id: idOf(written, 'the Test Case it created') }
  }

  async getTestCase(id: string): Promise<TestCase | undefined> {
    const held = await this.answer('read_test_case', { test_case_id: id })

    if (held === absent) {
      return undefined
    }

    // TestLink answers a read with the versions of a Test Case, and holds far
    // more about one than this project has Rules for. What is served is the
    // Fields, so a read answers a Test Case rather than a TestLink record.
    const version = first(held)

    if (version === undefined) {
      return undefined
    }

    return {
      name: text(version.name),
      summary: text(version.summary),
      preconditions: text(version.preconditions),
    }
  }

  async updateTestCase(id: string, testCase: TestCase): Promise<boolean> {
    // A Field the caller left out is left out of the update: testlink-mcp
    // ignores an empty one, so an omission cannot clear what TestLink holds.
    const applied = await this.answer('update_test_case', {
      test_case_id: id,
      data: { name: testCase.name, ...fieldsOf(testCase) },
    })

    return applied !== absent
  }

  async deleteTestCase(id: string): Promise<boolean> {
    return (await this.answer('delete_test_case', { test_case_id: id })) !== absent
  }

  async listProjects(): Promise<TestLinkContent> {
    const listed = await this.answer('list_projects', {})

    if (listed === absent) {
      // Nothing was named to be missing, so TestLink reporting absence here is
      // TestLink not making sense rather than an answer a caller can act on.
      throw new Error('TestLink reported no Projects to list.')
    }

    return listed
  }

  async createProject(project: NewProject): Promise<{ id: string }> {
    const created = await this.answer('create_project', {
      name: project.name,
      prefix: project.prefix,
      ...settingsOf(project),
    })

    if (created === absent) {
      // Nothing was named to be missing, so this is TestLink not making sense
      // rather than an answer a caller could act on.
      throw new Error('TestLink reported the Project it was asked to create as missing.')
    }

    return { id: idOf(created, 'the Project it created') }
  }

  async updateProject(projectId: string, changes: ProjectChanges): Promise<boolean> {
    const applied = await this.answer('update_project', {
      project_id: projectId,
      ...given({ name: changes.name }),
      ...settingsOf(changes),
    })

    return applied !== absent
  }

  async deleteProject(projectId: string, confirmPrefix: string): Promise<ProjectDeletion> {
    const deleted = await this.answer(
      'delete_project',
      { project_id: projectId, confirm_prefix: confirmPrefix },
      // The interlock refusing is the caller's to correct, so it is read here
      // rather than escalated: a caller told TestLink is down restates nothing.
      reportsUnconfirmed,
    )

    if (deleted === unconfirmed) {
      return 'unconfirmed'
    }

    return deleted === absent ? 'absent' : 'deleted'
  }

  async listTestSuites(
    projectId: string,
    parentSuiteId?: string,
  ): Promise<TestLinkContent | undefined> {
    return this.listed('list_test_suites', {
      project_id: projectId,
      ...given({ parent_suite_id: parentSuiteId }),
    })
  }

  async listTestCasesInSuite(suiteId: string): Promise<TestLinkContent | undefined> {
    return this.listed('list_test_cases_in_suite', { suite_id: suiteId })
  }

  async createTestSuite(
    projectId: string,
    suite: NewTestSuite,
    parentSuiteId?: string,
  ): Promise<{ id: string } | undefined> {
    const created = await this.answer('create_test_suite', {
      project_id: projectId,
      suite_name: suite.name,
      ...given({ details: suite.details, parent_id: parentSuiteId }),
    })

    if (created === absent) {
      return undefined
    }

    return { id: idOf(created, 'the Test Suite it created') }
  }

  async updateTestSuite(
    projectId: string,
    suiteId: string,
    changes: TestSuiteChanges,
  ): Promise<boolean> {
    const applied = await this.answer('update_test_suite', {
      suite_id: suiteId,
      project_id: projectId,
      data: changes,
    })

    return applied !== absent
  }

  async deleteTestSuite(suiteId: string): Promise<boolean> {
    return (await this.answer('delete_test_suite', { suite_id: suiteId })) !== absent
  }

  /**
   * A listing of what TestLink holds under something the caller named. The
   * thing named not being there is an answer, the same as it is for a read:
   * a caller listing the Suites of a Project that is not there has an id to
   * correct, not an outage to escalate.
   */
  private async listed(
    tool: string,
    args: Record<string, unknown>,
  ): Promise<TestLinkContent | undefined> {
    const listed = await this.answer(tool, args)

    return listed === absent ? undefined : listed
  }

  /**
   * One tool call, read as one of three outcomes: what TestLink answered, the
   * thing named not being there, or a throw for everything else.
   *
   * Absence is read only out of what TestLink reported about the call — the
   * error it replied with, or the code-and-message it sometimes puts where a
   * result should go. It is never read out of served content, because a Test
   * Case is entitled to be about a file that does not exist and reading its own
   * words back as absence would make it disappear.
   *
   * Anything unreadable throws, so an unrecognised failure escalates as an
   * outage rather than being answered as absence: a caller told a Test Case is
   * not there stops looking for it.
   *
   * `alsoTheCallers` names one further failure this particular call's caller can
   * correct, for the calls that have one. It is read before absence, so a call
   * that fails for its own reason is not first mistaken for something missing.
   */
  private async answer(
    tool: string,
    args: Record<string, unknown>,
    alsoTheCallers?: (message: string) => boolean,
  ): Promise<TestLinkContent | typeof absent | typeof unconfirmed> {
    const result = await this.tools.call(tool, args)

    if (result.isError) {
      return this.place(tool, result.text, alsoTheCallers)
    }

    const content: unknown = JSON.parse(result.text)
    const reported = reportedProblem(content)

    if (reported !== undefined) {
      return this.place(tool, reported, alsoTheCallers)
    }

    const denied = deniedIn(content)

    if (denied !== undefined) {
      throw new Error(`TestLink did not complete ${tool}: ${denied}`)
    }

    return content
  }

  /**
   * Which of the outcomes a caller can act on this failure is, or none of them,
   * in which case it escalates. Escalating is the default deliberately: a
   * failure nobody has taught this client to read is an outage until someone
   * has, because answering it as absence would send a caller away.
   */
  private place(
    tool: string,
    message: string,
    alsoTheCallers?: (message: string) => boolean,
  ): typeof absent | typeof unconfirmed {
    if (alsoTheCallers?.(message) === true) {
      return unconfirmed
    }

    if (reportsMissingTool(message)) {
      throw new Error(
        `testlink-mcp does not provide ${tool}, so it is older than the ${expectedTestLinkMcp} this client calls: ${message}`,
      )
    }

    if (reportsAbsence(message)) {
      return absent
    }

    throw new Error(`TestLink could not be reached through ${tool}: ${message}`)
  }
}

/** TestLink holds nothing under what the call named. */
const absent = Symbol('absent')

/** The caller did not restate the Project's prefix, so TestLink deleted nothing. */
const unconfirmed = Symbol('unconfirmed')

/**
 * The interlock refusing. TestLink asks a caller deleting a Project to restate
 * its prefix, and says so in its own words when the restatement does not match.
 */
function reportsUnconfirmed(message: string): boolean {
  return /Confirmation failed/i.test(message)
}

/**
 * The arguments the caller actually gave, so an omission is left unsent rather
 * than sent empty. Only an omission is dropped: `false` and an empty string are
 * things a caller said, and a setting turned off has to reach TestLink as one.
 */
function given(args: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(Object.entries(args).filter(([, value]) => value !== undefined))
}

/** The settings of a Project, as testlink-mcp names them. */
function settingsOf(project: NewProject | ProjectChanges): Record<string, unknown> {
  return given({
    notes: project.notes,
    active: project.active,
    is_public: project.isPublic,
    color: 'color' in project ? project.color : undefined,
    requirements_enabled: project.requirementsEnabled,
    test_priority_enabled: project.testPriorityEnabled,
    automation_enabled: project.automationEnabled,
    inventory_enabled: project.inventoryEnabled,
  })
}

/** The Fields carrying content, as testlink-mcp takes them. */
function fieldsOf(testCase: TestCase): Record<string, string> {
  return { summary: testCase.summary, ...given({ preconditions: testCase.preconditions }) }
}

/**
 * The id TestLink gave what it just created. TestLink reports it either at the
 * top of the result or in what it says about the operation, so both are read —
 * and a result carrying neither is a write that did not land, however
 * successfully it was phrased. Answering an id here is what makes the write
 * complete, so there is nothing to answer when TestLink named none.
 */
function idOf(content: TestLinkContent, subject: string): string {
  const created = first(content)
  const reported = record(created?.additionalInfo)
  const id = created?.id ?? reported?.id

  // `0` and the empty string are ids nothing is held under, so they are read as
  // the absence of one rather than passed back for a caller to read with.
  if ((typeof id !== 'string' && typeof id !== 'number') || String(id) === '' || Number(id) === 0) {
    throw new Error(`TestLink reported no id for ${subject}: ${JSON.stringify(content)}`)
  }

  return String(id)
}

/**
 * The problem TestLink reported about a call it did not refuse outright.
 * TestLink answers some failures as a code and a message where the result
 * should be, rather than as an error, so both readings meet here. A reply
 * carrying no code is content, and is never read for a problem.
 */
function reportedProblem(content: unknown): string | undefined {
  const reported = first(content)

  if (reported?.code === undefined || typeof reported.message !== 'string') {
    return undefined
  }

  return reported.message
}

/**
 * TestLink saying the operation did not happen. A write answers a caller only
 * once TestLink has confirmed it, and a reply that denies the write is not a
 * confirmation however cleanly it arrived. Only an explicit denial counts: a
 * reply that says nothing about status — every listing, and a read — is not
 * read as one.
 */
function deniedIn(content: unknown): string | undefined {
  const reported = first(content)

  if (reported?.status !== false) {
    return undefined
  }

  return typeof reported.message === 'string'
    ? reported.message
    : 'TestLink gave no reason for it.'
}

/**
 * Whether TestLink is reporting that what the call named is not there. Two
 * wordings, because two things do the reporting: TestLink says a thing "does
 * not exist", and testlink-mcp says "not found" for the Projects it resolves
 * itself before calling TestLink at all. Both are matched narrowly, because
 * everything this does not match is escalated as an outage instead.
 */
function reportsAbsence(message: string): boolean {
  return /does not exist|not found/i.test(message)
}

/**
 * The testlink-mcp this client is written against. It lives here because it is
 * the client that knows which tools it calls, and it is what launching the
 * server pins to, so the two cannot drift apart.
 */
export const expectedTestLinkMcp = '1.6.0'

/**
 * Whether testlink-mcp is reporting a tool it does not have. A server older
 * than the version above answers this rather than failing anything in TestLink,
 * so it is the version showing through and not a word about TestLink, which is
 * reachable and healthy in every case that reaches here.
 */
function reportsMissingTool(message: string): boolean {
  return /Unknown tool/i.test(message)
}

/** What TestLink sent, whether it sent one or a list of them. */
function first(content: unknown): Record<string, unknown> | undefined {
  return record(Array.isArray(content) ? content[0] : content)
}

function record(value: unknown): Record<string, unknown> | undefined {
  return typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : undefined
}

/** A Field as it is served: what TestLink holds, and empty where it holds nothing. */
function text(value: unknown): string {
  return typeof value === 'string' ? value : ''
}

import pg from 'pg'

import type { Queries } from './queries.js'
import type {
  DocumentStore,
  ListedReferenceDocument,
  ReferenceDocument,
} from './reference-document.js'
import type { StoredRule } from './rule-set.js'

/**
 * Whether an operator has applied `schema.sql` to this database. Asked outright
 * rather than read out of the error a missing table would raise: absence is told
 * from unreachability by what the database says about itself, never by matching
 * the text of a failure.
 */
async function hasSchema(queries: Queries): Promise<boolean> {
  const rows = await queries.run(
    "select 1 from information_schema.tables where table_name = 'rules'",
  )

  return rows.length > 0
}

/**
 * The enabled Exceptions, gathered under the Rule each belongs to. Read in a
 * statement of its own rather than joined: a Rule with no Exception is the
 * common one, and a join would answer for it with a row of nulls to tell apart
 * from a row carrying a phrase.
 */
async function exceptionsByRule(queries: Queries): Promise<Map<number, string[]>> {
  const rows = await queries.run(
    'select rule, phrase from rule_exceptions where enabled order by id',
  )
  const byRule = new Map<number, string[]>()

  for (const row of rows) {
    const rule = Number(row.rule)
    const phrases = byRule.get(rule)

    if (phrases === undefined) {
      byRule.set(rule, [String(row.phrase)])
      continue
    }

    phrases.push(String(row.phrase))
  }

  return byRule
}

/**
 * The database, read only. This project makes no write to it at all (ADR-0006),
 * so there is no method here that could relax a Rule or author a Reference
 * Document — the server holds an object that cannot do either.
 *
 * Absence is an answer rather than a failure: a document the database holds
 * nothing under answers `undefined`, where the database being unreachable
 * throws out of `pg` and reaches the caller as a server error.
 */
export class PostgresStore implements DocumentStore {
  constructor(private readonly queries: Queries) {}

  /**
   * The enabled Rules, each carrying its enabled Exceptions. Read once at
   * startup and never again, which is the property ADR-0004 keeps: a running
   * server judges every Test Case by the Rules it started with.
   *
   * A disabled Rule is not read at all. It stops firing exactly as completely as
   * a deleted one would, and its row stays so a Violation logged against it can
   * still be explained (ADR-0007).
   *
   * A database the schema has never been applied to has no tables at all, which
   * is still "no Rules" and not an outage — so it answers none here and the
   * server says what to do, rather than dying on a missing table.
   */
  async rules(): Promise<StoredRule[]> {
    if (!(await hasSchema(this.queries))) {
      return []
    }

    const rows = await this.queries.run(
      'select id, rule_id, content_kind, field, category, looks_for, flanked, reason from rules where enabled order by id',
    )
    const exceptions = await exceptionsByRule(this.queries)

    return rows.map((row) => ({
      ruleId: String(row.rule_id),
      contentKind: String(row.content_kind),
      field: String(row.field),
      category: String(row.category),
      looksFor: String(row.looks_for),
      // The column is nullable, and only a Symbol Rule ever carries it.
      flanked: row.flanked === null || row.flanked === undefined ? null : String(row.flanked),
      reason: String(row.reason),
      exceptions: exceptions.get(Number(row.id)) ?? [],
    }))
  }

  async listDocuments(): Promise<ListedReferenceDocument[]> {
    const rows = await this.queries.run('select id, title from reference_documents order by id')

    return rows.map((row) => ({ id: String(row.id), title: String(row.title) }))
  }

  async getDocument(id: string): Promise<ReferenceDocument | undefined> {
    const [row] = await this.queries.run(
      'select title, body from reference_documents where id = $1',
      [id],
    )

    return row === undefined ? undefined : { title: String(row.title), body: String(row.body) }
  }
}

/** What this project needs of a connected client, which is one method of it. */
interface Connected {
  query(sql: string, parameters?: unknown[]): Promise<{ rows: unknown[] }>
}

/**
 * Puts a connected client behind the statements-and-rows seam everything above
 * speaks in. Exported so that a test running an in-process Postgres reaches it
 * through this same adapter rather than through a copy of it.
 */
export function queriesFrom(client: Connected): Queries {
  return {
    async run(sql: string, parameters?: unknown[]) {
      const { rows } = await client.query(sql, parameters)
      return rows as Record<string, unknown>[]
    },
  }
}

/**
 * Opens the one connection this process needs. Narrow by design: everything
 * above it speaks in statements and rows, so the store is exercised without a
 * database and this is the only part that needs one.
 */
export async function connectToPostgres(url: string): Promise<Queries & { close(): Promise<void> }> {
  const client = new pg.Client({ connectionString: url })

  await client.connect()

  return { ...queriesFrom(client), close: () => client.end() }
}

import type { FieldName, RuleSet, SymbolRule, TermRule } from './rule-set.js'

/**
 * One Rule firing on one Field, as the caller reads it. It carries where to
 * look and why, and deliberately no replacement: the caller decides the wording,
 * and a suggestion would make this API an author rather than a check.
 */
export interface Violation {
  field: FieldName
  /** The id the operator gave the Rule, which tells two Rules on one Field apart. */
  rule: string
  reason: string
  /** The text that matched, and where it starts in the Field. */
  text: string
  offset: number
}

/**
 * Every Violation a piece of content produces. Fields are checked
 * independently, and each Field against every Rule bound to it, so the caller
 * corrects in one pass rather than resubmitting to discover the next problem.
 *
 * Written against Fields rather than against a Test Case, because a Reference
 * Document has Fields too and is checked the same way. The caller passes the
 * Rule Sets bound to that content, so a Rule can only ever reach a Field of the
 * content it was written for.
 */
export function findViolations<Field extends FieldName>(
  content: Partial<Record<Field, string>>,
  ruleSets: Map<Field, RuleSet>,
): Violation[] {
  const found: Violation[] = []

  for (const [field, rules] of ruleSets) {
    const value = content[field]

    if (value === undefined) {
      continue
    }

    for (const rule of rules) {
      const fired =
        rule.type === 'term'
          ? termViolations(field, value, rule)
          : symbolViolations(field, value, rule)

      // Suppression is applied per Rule, with only that Rule's own Exceptions,
      // so an Exception cannot reach a Rule it was not written for.
      const suppressed = suppressedSpans(value, rule.exceptions)

      found.push(...fired.filter((violation) => !isSuppressed(violation, suppressed)))
    }
  }

  return found
}

/** Where a word or phrase was found in a Field. */
interface Span {
  start: number

/** A Test Case as submitted for validation and written through to TestLink. */
export interface TestCase {
  name: string
  summary: string
  preconditions?: string
}

/**
 * Where in TestLink a Test Case is created. Supplied per submission rather than
 * fixed at deployment: TestLink is the store the caller works in, so which
 * Project and which Test Suite a case belongs to is the caller's to say.
 */
export interface Placement {
  projectId: string
  suiteId: string
}

/**
 * What a caller says about a Project it is creating. The prefix is stamped into
 * every Test Case external id the Project ever holds, and TestLink will not
 * change it afterwards, so it is set here and appears in no change.
 */
export interface NewProject {
  name: string
  prefix: string
  notes?: string
  active?: boolean
  isPublic?: boolean
  requirementsEnabled?: boolean
  testPriorityEnabled?: boolean
  automationEnabled?: boolean
  inventoryEnabled?: boolean
}

/** What a caller may change about a Project. Its prefix is not among them. */
export interface ProjectChanges {
  name?: string
  notes?: string
  active?: boolean
  isPublic?: boolean
  color?: string
  requirementsEnabled?: boolean
  testPriorityEnabled?: boolean
  automationEnabled?: boolean
  inventoryEnabled?: boolean
}

/**
 * What became of a Project delete. Deleting a Project takes every Suite, Test
 * Case, Plan, Build, Execution and Requirement under it with it, so TestLink
 * asks the caller to restate the Project's own prefix before it does. Getting
 * that restatement wrong is the caller's to correct — it is told apart from the
 * Project not being there, and from TestLink not answering, because all three
 * would otherwise arrive as the same failure.
 */
export type ProjectDeletion = 'deleted' | 'absent' | 'unconfirmed'

/** What a caller says about a Test Suite it is creating. */
export interface NewTestSuite {
  name: string
  details?: string
}

/** What a caller may change about a Test Suite. Where it sits is not one of them. */
export interface TestSuiteChanges {
  name?: string
  details?: string
}

/**
 * What TestLink reports about its own structure — Projects, Test Suites, and
 * the Test Cases a Suite holds. Left unmodelled because no Rule binds to it: it
 * is served on through, not checked, so giving it a shape here would invent
 * vocabulary the project does not have.
 */
export type TestLinkContent = unknown

/**
 * The path to TestLink, read and write. Substituted in tests so the HTTP
 * surface can be exercised without a TestLink instance.
 *
 * Absence is an answer everywhere it can happen: an operation naming something
 * TestLink holds nothing under answers `undefined`, or `false` where it has no
 * content to answer with. Only TestLink being unreachable throws. Reporting the
 * two apart here is what lets every route answer them apart, rather than
 * reading an error message to guess which happened.
 *
 * The client reports content and never a judgement about it: what fired on that
 * content is decided by the Rules, above this interface.
 */
export interface TestLinkClient {
  /** Answers the id TestLink gave the Test Case, or nothing where it holds no such Test Suite. */
  createTestCase(placement: Placement, testCase: TestCase): Promise<{ id: string } | undefined>
  getTestCase(id: string): Promise<TestCase | undefined>
  /** Answers whether the Test Case was there to update. */
  updateTestCase(id: string, testCase: TestCase): Promise<boolean>
  /** Answers whether the Test Case was there to delete. */
  deleteTestCase(id: string): Promise<boolean>

  listProjects(): Promise<TestLinkContent>
  /** Answers the id TestLink gave the Project. */
  createProject(project: NewProject): Promise<{ id: string }>
  /** Answers whether the Project was there to update. */
  updateProject(projectId: string, changes: ProjectChanges): Promise<boolean>
  /** Deletes a Project and everything under it, once the caller has restated its prefix. */
  deleteProject(projectId: string, confirmPrefix: string): Promise<ProjectDeletion>
  /** The Test Suites directly under a Project, or under `parentSuiteId` where one is named. */
  listTestSuites(projectId: string, parentSuiteId?: string): Promise<TestLinkContent | undefined>
  listTestCasesInSuite(suiteId: string): Promise<TestLinkContent | undefined>

  /** Answers the id TestLink gave the Test Suite, or nothing where it holds no such Project. */
  createTestSuite(
    projectId: string,
    suite: NewTestSuite,
    parentSuiteId?: string,
  ): Promise<{ id: string } | undefined>
  /** Answers whether the Test Suite was there to update. */
  updateTestSuite(
    projectId: string,
    suiteId: string,
    changes: TestSuiteChanges,
  ): Promise<boolean>
  /** Answers whether the Test Suite was there to delete. */
  deleteTestSuite(suiteId: string): Promise<boolean>
}

