import { spawn, type ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'

import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { expectedTestLinkMcp } from '../src/mcp-testlink-client.js'

/**
 * What this proves: what the server refuses is refused all the way down, and
 * what it accepts reaches TestLink. Every claim here is about what TestLink
 * holds afterwards rather than about the status code that was answered — a
 * status code is a thing any substitute can produce, and the rest of this suite
 * already produces all of them against `stub-testlink-client.ts`.
 *
 * Six paths, each a caller action and what must be true of TestLink after it:
 *
 *   1. A Rejection writes nothing. A Test Case violating one of the Rules the
 *      operator actually applied is answered 422, and TestLink has issued no
 *      Test Case id in any Project and holds nothing under the name that was
 *      sent. The Rules doing the rejecting are the 445 rows in the real
 *      database, not rules this file wrote.
 *   2. An accepted update reaches TestLink. A Test Case is written, then
 *      updated, and TestLink's own tree reports it under the new name and no
 *      longer under the old one.
 *   3. A rejected update leaves it alone. The same Test Case, updated with
 *      wording a Rule catches, is answered 422 and TestLink still holds exactly
 *      what path 2 put there.
 *   4. A Test Suite TestLink does not hold, listed, is the caller's mistake to
 *      correct — a 404 naming it — rather than an outage.
 *   5. The same Test Suite, updated: a 404, and TestLink holds nothing under
 *      that id afterwards. An update reported as applied to a Test Suite that
 *      is not there is a confirmation of something that did not happen.
 *   6. The same Test Suite, deleted: a 404, and nothing else was removed.
 *
 * Paths 4, 5 and 6 are about wording rather than about status codes.
 * `McpTestLinkClient.place` decides between absence and an outage by matching
 * the words TestLink failed in — `reportsAbsence` looks for "does not exist" or
 * "not found" — and every other file in this suite matches that reading against
 * strings the suite itself wrote. Only a real TestLink can say whether the words
 * it actually fails in are the words being matched.
 *
 * Nothing is substituted. One thing is configured rather than defaulted, and it
 * is the same seam `system-write-reaches-testlink.test.ts` names: `src/server.ts`
 * launches testlink-mcp in a container with no `--network` flag, which cannot
 * reach a TestLink published on the host's own localhost. So the launch is
 * overridden with the host-network form, through the two settings the server
 * reads for exactly that purpose, and the version is imported from the client so
 * it cannot drift from the testlink-mcp the client is written against.
 *
 * What it needs, none of which it creates for itself:
 *
 *   docker compose up -d
 *   psql "$DATABASE_URL" -f schema.sql
 *   psql "$DATABASE_URL" -f default-rules.sql
 *
 * and a `.env` naming that database, that TestLink and an API key for it. With
 * any of them absent this file fails rather than skips.
 */

/** Where this run's server listens. Its own port: the file beside it uses 8131. */
const port = Number(process.env.SYSTEM_REFUSAL_TEST_PORT ?? 8132)
const server = `http://127.0.0.1:${port}`

const repository = fileURLToPath(new URL('..', import.meta.url))

/**
 * A Field of the shipped Rules that this file relies on being enabled, and the
 * wording that fires it. Named here rather than inline so a failure says which
 * Rule was being counted on: if `default-rules.sql` has not been applied, or
 * this Rule has been switched off, the 422 never comes and the reason is this
 * constant rather than the server.
 */
const shippedRule = { id: 'no-basically', field: 'summary', firesOn: 'basically' }

/**
 * The fixture this file works in. Its own Project rather than the one
 * `system-write-reaches-testlink.test.ts` uses, because vitest runs files
 * side by side and two runs doing look-up-or-create against one Project would
 * race to create it.
 *
 * Stable names, never suffixed: a run that dies before its teardown leaves them
 * findable, so the next run reuses what it finds instead of filling TestLink
 * with near-duplicates. The prefix is stamped into the Project forever and
 * TestLink will not have two, which is another reason not to generate one.
 */
const fixture = {
  project: { name: 'Validator Refusal Test', prefix: 'VRFX' },
  suite: { name: 'Refused and unchanged' },
  /**
   * The Test Case paths 2 and 3 work on, worded to violate none of the shipped
   * Rules — no colon, no hyphen, none of the terms in `default-rules.sql` — so
   * that the write under it is accepted and the only Rejection in this file is
   * the one a path asked for.
   */
  written: {
    name: 'Guest device reaches the portal page',
    summary: 'A guest device associates with the open SSID and reaches the portal page.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /** What path 2 updates it to. Clean for the same reason, and different in every Field. */
  updated: {
    name: 'Guest device keeps the portal session',
    summary: 'A guest device holds the portal session while it moves between access points.',
    preconditions: 'Two access points broadcast the open SSID.',
  },
  /**
   * What path 1 submits and what path 3 tries to update to. Clean apart from the
   * one word the shipped Rule above catches, so the 422 names that Rule and
   * nothing else, and a Rule set that has drifted says so by naming a different
   * one.
   */
  refused: {
    name: 'Guest device leaves the open SSID',
    summary: `A guest device ${shippedRule.firesOn} drops off the open SSID and loses the portal session.`,
    preconditions: 'The open SSID is broadcast on the access point.',
  },
  /**
   * The Test Suite that supplies an id TestLink does not hold. Placed and then
   * removed, so the id paths 4 to 6 use is one TestLink issued and has given up,
   * rather than a number picked for being free — a number free today is a number
   * some later run finds taken, and a check against one is a check against
   * arithmetic instead of against absence.
   */
  removedSuite: { name: 'Removed so its id is held by nothing' },
}

/** What the server answered, kept whole so a failure can quote it. */
interface Answer {
  status: number
  text: string
  body: any
}

async function call(method: string, path: string, payload?: unknown): Promise<Answer> {
  const response = await fetch(`${server}${path}`, {
    method,
    ...(payload === undefined
      ? {}
      : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }),
  })
  const text = await response.text()

  return { status: response.status, text, body: text === '' ? undefined : JSON.parse(text) }
}

/**
 * The answer, or a failure naming what was asked and what came back. Written as
 * a throw rather than an expectation so the same reading works in a hook: a
 * TestLink that is not answering has to say so where it happened, not as an
 * undefined further down.
 */
function answered(what: string, answer: Answer, status: number): Answer {
  if (answer.status !== status) {
    throw new Error(`${what} answered ${answer.status} rather than ${status}: ${answer.text}`)
  }

  return answer
}

/**
 * A listing, reading a Project or a Test Suite that holds nothing yet as the
 * empty listing it is.
 *
 * TestLink reports "is empty" as an API failure rather than as an empty result,
 * and `McpTestLinkClient` matches only "does not exist" and "not found", so that
 * wording escalates as an outage and the server answers 500. That is worth an
 * issue of its own and it is not what this file is about: it shows up only on
 * the way to placing the fixture, on the first run against a TestLink that has
 * never held it. Read here, in the fixture path alone — every answer a path
 * itself reads is demanded outright.
 */
function listed(what: string, answer: Answer): { id: string; name: string }[] {
  if (answer.status === 500 && /is empty/i.test(answer.text)) {
    return []
  }

  return answered(what, answer, 200).body as { id: string; name: string }[]
}

let serverProcess: ChildProcess
/** Everything the server said, so a start that never completes reports its own reason. */
let said = ''
let projectId: string
let suiteId: string
let absentSuiteId: string
let writtenId: string | undefined

/** The real entry point, launched the way `npm run dev` launches it. */
async function startServer(): Promise<void> {
  serverProcess = spawn('npx', ['tsx', '--env-file-if-exists=.env', 'src/server.ts'], {
    cwd: repository,
    // Set here rather than in .env: what is set in the environment wins over the
    // file, so this names the port and the launch without editing anything.
    env: {
      ...process.env,
      PORT: String(port),
      TESTLINK_MCP_COMMAND: process.env.TESTLINK_MCP_COMMAND ?? 'docker',
      TESTLINK_MCP_ARGS:
        process.env.TESTLINK_MCP_ARGS ??
        JSON.stringify([
          'run',
          '--rm',
          '-i',
          '--network',
          'host',
          '-e',
          'TESTLINK_URL',
          '-e',
          'TESTLINK_API_KEY',
          `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
        ]),
    },
    // Its own group, so stopping it stops the testlink-mcp it spawned as well.
    detached: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })

  serverProcess.stdout?.on('data', (chunk) => (said += chunk))
  serverProcess.stderr?.on('data', (chunk) => (said += chunk))

  // Readiness is asked of the route that reads only the database, so a TestLink
  // that is down is reported by the step that needed it rather than as a server
  // that never started.
  for (let attempt = 0; attempt < 120; attempt++) {
    if (serverProcess.exitCode !== null) {
      throw new Error(`The server exited with ${serverProcess.exitCode} before it listened: ${said}`)
    }

    try {
      await call('GET', '/reference-documents')
      return
    } catch {
      await new Promise((wait) => setTimeout(wait, 500))
    }
  }

  throw new Error(`The server did not listen on ${port}: ${said}`)
}

function stopServer(): void {
  if (serverProcess?.pid !== undefined && serverProcess.exitCode === null) {
    try {
      process.kill(-serverProcess.pid, 'SIGTERM')
    } catch {
      serverProcess.kill('SIGTERM')
    }
  }
}

/** The fixture Project, reused where TestLink already holds one under this name. */
async function placeProject(): Promise<string> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)
  const held = (projects.body as { id: string; name: string }[]).find(
    (project) => project.name === fixture.project.name,
  )

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Project ${fixture.project.name}`,
    await call('POST', '/projects', {
      ...fixture.project,
      notes: 'Fixture Project for the system test that checks what a refusal leaves in TestLink.',
    }),
    201,
  )

  return String(created.body.id)
}

/** The fixture Test Suite under it, reused the same way and for the same reason. */
async function placeSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.suite.name)

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Test Suite ${fixture.suite.name}`,
    await call('POST', `/projects/${projectId}/suites`, {
      ...fixture.suite,
      details: 'Fixture Test Suite for the system test that checks what a refusal leaves in TestLink.',
    }),
    201,
  )

  return String(created.body.id)
}

/**
 * A Test Suite id TestLink no longer holds. Placed under the fixture Project and
 * removed again, because absence has to be something TestLink demonstrated
 * rather than something this file assumed: TestLink issues node ids from a
 * sequence and does not issue one twice, so an id it has given up is an id it
 * will never hold again.
 *
 * The name is stable and never suffixed, so a run that died between the place
 * and the remove leaves a Test Suite the next run finds and removes rather than
 * a second one beside it. The removal is verified before the id is handed on,
 * because an id whose Test Suite is still there would prove the opposite of what
 * paths 4 to 6 need and would do it silently.
 *
 * The removal is read rather than demanded, and it is the one place in this file
 * that is: path 6 exists precisely because deleting a Test Suite that is not
 * there may not answer 204. Here the Test Suite is there, so a 204 is what
 * should come — and the listing afterwards is what settles it either way.
 */
async function placeAndRemoveSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.removedSuite.name)

  const id =
    held !== undefined
      ? String(held.id)
      : String(
          answered(
            `Creating Test Suite ${fixture.removedSuite.name}`,
            await call('POST', `/projects/${projectId}/suites`, {
              ...fixture.removedSuite,
              details:
                'Placed and removed by the system test, so that its id is one TestLink holds nothing under.',
            }),
            201,
          ).body.id,
        )

  answered(
    `Removing Test Suite ${id}`,
    await call('DELETE', `/projects/${projectId}/suites/${id}`),
    204,
  )

  const remaining = listed(
    `Listing the Test Suites of Project ${projectId} after removing ${id}`,
    await call('GET', `/projects/${projectId}/suites`),
  )

  if (remaining.some((suite) => String(suite.id) === id)) {
    throw new Error(`Test Suite ${id} is still in Project ${projectId}, so its id is not free.`)
  }

  return id
}

/**
 * How many Test Cases TestLink has issued an id for, per Project — its own
 * count, served with every Project it lists. A count that has not moved in any
 * Project is TestLink having created no Test Case anywhere, which is what a
 * refusal has to be true of and what listing one Test Suite cannot say.
 */
async function testCaseCounts(): Promise<Record<string, string>> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)

  return Object.fromEntries(
    (projects.body as { id: string; tc_counter: string }[]).map((project) => [
      String(project.id),
      String(project.tc_counter),
    ]),
  )
}

/** What TestLink's own tree reports the fixture Test Suite holds. */
async function namesInSuite(): Promise<string[]> {
  return listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  ).map((held) => held.name)
}

/** What TestLink's own tree reports the fixture Project holds Test Suites under. */
async function suiteIdsInProject(): Promise<string[]> {
  return listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).map((suite) => String(suite.id))
}

/**
 * A Test Case one of this file's fixture names is already on, from a run that
 * failed before its teardown. Removed rather than written beside, so a leak
 * cannot accumulate and path 1's claim that TestLink holds nothing under the
 * refused name starts from a TestLink where that is true.
 */
async function removeLeftovers(): Promise<void> {
  const cases = listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  )
  const fixtureNames = [fixture.written.name, fixture.updated.name, fixture.refused.name]

  for (const held of cases) {
    if (fixtureNames.includes(held.name)) {
      answered(
        `Removing the leftover Test Case ${held.id}`,
        await call('DELETE', `/test-cases/${held.id}`),
        204,
      )
    }
  }
}

describe('what the running server refuses, and what TestLink holds afterwards', () => {
  beforeAll(async () => {
    await startServer()
    projectId = await placeProject()
    suiteId = await placeSuite()
    absentSuiteId = await placeAndRemoveSuite()
    await removeLeftovers()
  }, 120_000)

  afterAll(async () => {
    try {
      if (writtenId !== undefined) {
        answered(
          `Removing the Test Case ${writtenId} this run created`,
          await call('DELETE', `/test-cases/${writtenId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${writtenId}`,
          await call('GET', `/test-cases/${writtenId}`),
          404,
        )
      }
    } finally {
      stopServer()
    }
  }, 60_000)

  it('refuses a Test Case a shipped Rule catches, and TestLink is given nothing', async () => {
    const before = await testCaseCounts()

    const rejected = answered(
      `Submitting a Test Case the ${shippedRule.id} Rule catches`,
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.refused),
      422,
    )

    // The Rule that fired is one of the 445 rows in the database, so this also
    // says the server is judging by what the operator applied rather than by
    // anything this file supplied. A different Rule here is a Rule set that has
    // drifted, and it names itself.
    expect(rejected.body.violations).toContainEqual(
      expect.objectContaining({ field: shippedRule.field, rule: shippedRule.id }),
    )

    // The infrastructure, which is what separates this from a status code any
    // substitute could produce: TestLink issued no Test Case id in any Project,
    // and holds nothing in the fixture Test Suite under the name that was sent.
    expect(await testCaseCounts()).toEqual(before)
    expect(await namesInSuite()).not.toContain(fixture.refused.name)
  }, 60_000)

  it('carries an accepted update through to what TestLink holds', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.written),
      201,
    )

    writtenId = String(written.body.id)
    expect(writtenId).not.toBe('')

    answered(
      `Updating Test Case ${writtenId}`,
      await call('PUT', `/test-cases/${writtenId}`, fixture.updated),
      200,
    )

    // TestLink's own tree, which is a different call from the read below: the
    // Test Case is under the new name there and no longer under the old one, so
    // the update reached TestLink rather than only the answer.
    const names = await namesInSuite()
    expect(names).toContain(fixture.updated.name)
    expect(names).not.toContain(fixture.written.name)

    // And every Field TestLink now holds is the Field that was sent, read back
    // under the same id the write answered with.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
